async function loadDatabase(): Promise<Database> {
  let text: string;
  try {
    text = await Bun.file(databasePath).text();
  } catch (error) {
    if (isPlainObject(error) && error.code === "ENOENT") return { version: 1, nextId: 1, tasks: [] };
