      title,
      status: "open",
      tags: typeof tagsValue === "string" ? normalizeTags(tagsValue) : [],
      ...(due === undefined ? {} : { due }),
      createdAt: new Date().toISOString(),
    };
    database.nextId++;
    database.tasks.push(task);
    await saveDatabase(database);
    return task;
