  } catch (error) {
    if (isPlainObject(error) && error.code === "ENOENT") return { version: 1, nextId: 1, tasks: [] };
    fail(`cannot read database: ${error instanceof Error ? error.message : String(error)}`);
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    fail("database is not valid JSON");
  }
  return validateDatabase(parsed);
}

async function saveDatabase(database: Database): Promise<void> {
  const directory = dirname(databasePath);
  const temporary = join(directory, `.${basename(databasePath)}.${process.pid}.${crypto.randomUUID()}.tmp`);
  try {
    await writeFile(temporary, `${JSON.stringify(database, null, 2)}\n`, { encoding: "utf8", flag: "wx" });
    await rename(temporary, databasePath);
  } catch (error) {
    try { await unlink(temporary); } catch {}
    fail(`cannot write database: ${error instanceof Error ? error.message : String(error)}`);
  }
}

function parseOptions(args: string[], allowed: Record<string, boolean>): Record<string, string | true> {
  const options: Record<string, string | true> = {};
  for (let index = 0; index < args.length; index++) {
    const flag = args[index];
    if (!flag.startsWith("--") || !(flag in allowed)) fail(`unknown flag or argument: ${flag}`);
    if (flag in options) fail(`flag specified more than once: ${flag}`);
    if (allowed[flag]) {
      const value = args[++index];
      if (value === undefined || value.startsWith("--")) fail(`missing value for ${flag}`);
      options[flag] = value;
    } else {
      options[flag] = true;
    }
  }
  return options;
}

function parseId(value: string | undefined): number {
  if (value === undefined || !/^[1-9]\d*$/.test(value)) fail("ID must be a positive integer");
  const id = Number(value);
  if (!Number.isSafeInteger(id)) fail("ID is too large");
  return id;
}

function localToday(): string {
  const now = new Date();
  const year = String(now.getFullYear()).padStart(4, "0");
  const month = String(now.getMonth() + 1).padStart(2, "0");
  const day = String(now.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

async function run(args: string[]): Promise<unknown> {
  const [command, ...rest] = args;
  if (!command) fail("missing command");

  if (command === "add") {
    const options = parseOptions(rest, { "--title": true, "--tags": true, "--due": true });
    const titleValue = options["--title"];
    if (typeof titleValue !== "string") fail("missing required --title");
    const title = titleValue.trim();
    if (!title) fail("title must not be empty");
    const dueValue = options["--due"];
    const due = typeof dueValue === "string" ? parseDate(dueValue, "due date") : undefined;
    const tagsValue = options["--tags"];
    const database = await loadDatabase();
    const task: Task = {
      id: database.nextId,
      title,
      status: "open",
      tags: typeof tagsValue === "string" ? normalizeTags(tagsValue) : [],
      ...(due === undefined ? {} : { due }),
      createdAt: new Date().toISOString(),
    };
    database.nextId++;
    database.tasks.push(task);
    await saveDatabase(database);
    return task;
  }

  if (command === "list") {
    const options = parseOptions(rest, { "--status": true, "--tag": true, "--overdue": true });
    const status = options["--status"];
    if (status !== undefined && status !== "open" && status !== "done") fail("status must be open or done");
    const tagValue = options["--tag"];
    const tag = typeof tagValue === "string" ? normalizeTag(tagValue) : undefined;
    if (tagValue !== undefined && !tag) fail("tag must not be empty");
    const overdueValue = options["--overdue"];
    const overdue = typeof overdueValue === "string" ? parseDate(overdueValue, "overdue date") : undefined;
    const database = await loadDatabase();
    return database.tasks
      .filter((task) => status === undefined || task.status === status)
      .filter((task) => tag === undefined || task.tags.includes(tag))
      .filter((task) => overdue === undefined || (task.status === "open" && task.due !== undefined && task.due < overdue))
      .sort((left, right) => left.id - right.id);
  }

  if (command === "done") {
    if (rest.length !== 1) fail("usage: done ID");
    const id = parseId(rest[0]);
    const database = await loadDatabase();
    const task = database.tasks.find((candidate) => candidate.id === id);
    if (!task) fail(`task ${id} not found`);
    if (task.status === "open") {
      task.status = "done";
      task.completedAt = new Date().toISOString();
      await saveDatabase(database);
    }
    return task;
  }

  if (command === "delete") {
    if (rest.length !== 1) fail("usage: delete ID");
    const id = parseId(rest[0]);
    const database = await loadDatabase();
    const index = database.tasks.findIndex((task) => task.id === id);
    if (index === -1) fail(`task ${id} not found`);
    const [task] = database.tasks.splice(index, 1);
    await saveDatabase(database);
    return task;
  }

  if (command === "stats") {
    if (rest.length) fail(`unknown flag or argument: ${rest[0]}`);
    const database = await loadDatabase();
    const today = localToday();
    const open = database.tasks.filter((task) => task.status === "open");
    return {
      total: database.tasks.length,
      open: open.length,
      done: database.tasks.length - open.length,
      overdue: open.filter((task) => task.due !== undefined && task.due < today).length,
    };
  }

  fail(`unknown command: ${command}`);
}

try {
  const output = await run(Bun.argv.slice(2));
  console.log(JSON.stringify(output));
} catch (error) {
  const message = error instanceof Error ? error.message : String(error);
  console.log(JSON.stringify({ error: message }));
  console.error(`taskboard: ${message}`);
  process.exitCode = 1;
}
import { afterEach, beforeEach, describe, expect, test } from "bun:test";
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { tmpdir } from "node:os";

const cli = join(import.meta.dir, "..", "src", "cli.ts");
let directory: string;
let database: string;

beforeEach(async () => {
  directory = await mkdtemp(join(tmpdir(), "taskboard-test-"));
  database = join(directory, "tasks.json");
});

afterEach(async () => {
  await rm(directory, { recursive: true, force: true });
});

async function invoke(...args: string[]) {
  const process = Bun.spawn(["bun", "run", cli, ...args], {
    cwd: directory,
    env: { ...Bun.env, TASKBOARD_FILE: database },
    stdout: "pipe",
    stderr: "pipe",
  });
  const [stdout, stderr, exitCode] = await Promise.all([
    new Response(process.stdout).text(),
    new Response(process.stderr).text(),
    process.exited,
  ]);
  const lines = stdout.trim().split("\n");
  expect(lines).toHaveLength(1);
  return { exitCode, output: JSON.parse(lines[0]), stderr };
}

describe("taskboard CLI", () => {
  test("persists tasks, normalizes tags, filters, and keeps stable ids", async () => {
    const first = await invoke("add", "--title", " First task ", "--tags", "Work, work, URGENT", "--due", "2024-01-01");
    expect(first.exitCode).toBe(0);
    expect(first.output).toMatchObject({ id: 1, title: "First task", status: "open", tags: ["work", "urgent"], due: "2024-01-01" });
    expect(Date.parse(first.output.createdAt)).not.toBeNaN();

    const second = await invoke("add", "--title", "Second", "--tags", "home");
    expect(second.output.id).toBe(2);
    expect((await invoke("list", "--status", "open", "--tag", "WORK")).output.map((task: { id: number }) => task.id)).toEqual([1]);
    expect((await invoke("list", "--overdue", "2024-01-02")).output.map((task: { id: number }) => task.id)).toEqual([1]);

    expect((await invoke("delete", "1")).exitCode).toBe(0);
    expect((await invoke("add", "--title", "Third")).output.id).toBe(3);
  });

  test("done is idempotent and stats count only open overdue tasks", async () => {
    await invoke("add", "--title", "Old", "--due", "2000-01-01");
    await invoke("add", "--title", "Open");
    const done = await invoke("done", "1");
    const repeated = await invoke("done", "1");
    expect(repeated.output.completedAt).toBe(done.output.completedAt);
    expect(await invoke("stats")).toMatchObject({ exitCode: 0, output: { total: 2, open: 1, done: 1, overdue: 0 } });
  });

  test("rejects invalid input and preserves a malformed database", async () => {
    expect((await invoke("add", "--title", "x", "--due", "2023-02-29")).exitCode).not.toBe(0);
    expect((await invoke("add", "--title", " ")).exitCode).not.toBe(0);
    expect((await invoke("list", "--wat")).exitCode).not.toBe(0);

    const malformed = "{broken\n";
    await writeFile(database, malformed);
    const result = await invoke("add", "--title", "Must not overwrite");
    expect(result.exitCode).not.toBe(0);
    expect(result.stderr).toContain("not valid JSON");
    expect(await readFile(database, "utf8")).toBe(malformed);
  });

  test("missing tasks fail", async () => {
    expect((await invoke("done", "99")).exitCode).not.toBe(0);
    expect((await invoke("delete", "99")).exitCode).not.toBe(0);
  });
});
# Taskboard CLI

A dependency-free TypeScript task manager for [Bun](https://bun.sh/). Tasks are stored in `.taskboard.json` in the current directory, or at the path in `TASKBOARD_FILE`. Database updates use a sibling temporary file followed by an atomic rename.

## Usage

```sh
bun run src/cli.ts add --title "Ship release" --tags work,urgent --due 2026-09-10
bun run src/cli.ts list --status open --tag work
bun run src/cli.ts list --overdue 2026-09-11
bun run src/cli.ts done 1
bun run src/cli.ts delete 1
bun run src/cli.ts stats
```

Every invocation writes exactly one JSON value to stdout. Errors also write a short diagnostic to stderr and exit non-zero. Tags are trimmed, lowercased, and deduplicated. Dates must be real calendar dates in `YYYY-MM-DD` form.

To use another database:

```sh
TASKBOARD_FILE=/path/to/tasks.json bun run src/cli.ts list
```

